mapper.sql:
FROM ast_device d
WHERE d.tenant_id = #{query.tenantId}
  AND d.deleted = b'0'

  AND (
    d.project_id IN

      #{projectId}

    OR EXISTS (
      SELECT 1
      FROM ast_device_project_relationship r
      WHERE r.tenant_id = d.tenant_id
        AND r.device_sn = d.sn
        AND r.project_id IN

          #{projectId}

        AND r.effective_from <= CURRENT_TIMESTAMP(3)
        AND (r.effective_to IS NULL OR r.effective_to > CURRENT_TIMESTAMP(3))
        AND r.deleted = b'0'
    )
  )


  AND d.sn = #{query.sn}


  AND d.product_code = #{query.productCode}


  AND d.project_id = #{query.projectId}


  AND d.customer_id = #{query.customerId}

FROM ast_device d WHERE d.tenant_id = #{query.tenantId} AND d.deleted = b'0' AND ( d.project_id IN
#{projectId}
OR EXISTS ( SELECT 1 FROM ast_device_project_relationship pr WHERE pr.tenant_id = d.tenant_id AND pr.device_sn = d.sn AND pr.project_id IN
#{projectId}
AND pr.effective_from <= CURRENT_TIMESTAMP(3) AND (pr.effective_to IS NULL OR pr.effective_to > CURRENT_TIMESTAMP(3)) AND pr.deleted = b'0' ) ) AND ( d.customer_id = #{query.customerId} OR EXISTS ( SELECT 1 FROM ast_device_customer_relationship r WHERE r.tenant_id = d.tenant_id AND r.device_sn = d.sn AND r.customer_id = #{query.customerId} AND r.effective_from <= CURRENT_TIMESTAMP(3) AND (r.effective_to IS NULL OR r.effective_to > CURRENT_TIMESTAMP(3)) AND r.deleted = b'0' ) )

mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM ast_device d
    WHERE d.tenant_id = #{query.tenantId}
      AND d.id = #{query.deviceId}
      AND d.deleted = b'0'
      AND (
        d.project_id IN

          #{projectId}

        OR EXISTS (
          SELECT 1
          FROM ast_device_project_relationship r
          WHERE r.tenant_id = d.tenant_id
            AND r.device_sn = d.sn
            AND r.project_id IN

              #{projectId}

            AND r.effective_from <= CURRENT_TIMESTAMP(3)
            AND (r.effective_to IS NULL OR r.effective_to > CURRENT_TIMESTAMP(3))
            AND r.deleted = b'0'
        )
      )
)
